function openRateDialog(row, valueInput, refreshRateSummary) {
  const dialog = $("#rateDialog"), form = $("#rateForm"), monthsInput = $("#rateMonths"), error = $("#rateError");
  const hadRate = Number(row.dataset.rateioMeses) > 1;
  monthsInput.value = String(hadRate ? Number(row.dataset.rateioMeses) : 12);
  $("#removeRate").hidden = !hadRate;
  error.textContent = "";
  const updatePreview = () => {
    const months = Math.min(120, Math.max(2, Number(monthsInput.value) || 2));
    const total = moneyInputNumber(valueInput.value);
    const dateValue = $("#entryForm").data.value || localDateISO();
    const start = new Date(`${dateValue.slice(0, 7)}-01T12:00:00`);
    const end = new Date(start.getFullYear(), start.getMonth() + months - 1, 1, 12);
    const monthLabel = (date) => date.toLocaleDateString("pt-BR", { month: "short", year: "numeric" }).replace(". de ", "/").replace(" de ", "/");
    $("#rateItemValue").textContent = money(total);
    $("#rateStart").textContent = monthLabel(start);
    $("#rateEnd").textContent = monthLabel(end);
    $("#rateInstallment").textContent = `${money(IndicatorCalc.installmentPreview(total, months).regularInstallment)}/mês`;
  };
  monthsInput.oninput = updatePreview;
  $("#rateMinus").onclick = () => { monthsInput.value = String(Math.max(2, (Number(monthsInput.value) || 2) - 1)); updatePreview(); };
  $("#ratePlus").onclick = () => { monthsInput.value = String(Math.min(120, (Number(monthsInput.value) || 2) + 1)); updatePreview(); };
  $("#closeRateDialog").onclick = $("#cancelRate").onclick = () => dialog.close();
  $("#removeRate").onclick = () => { row.dataset.rateioMeses = ""; refreshRateSummary(); dialog.close(); };
  form.onsubmit = (event) => {
    event.preventDefault();
    const months = Number(monthsInput.value);
    if (!Number.isInteger(months) || months < 2 || months > 120) {
      error.textContent = "Informe uma quantidade entre 02 e 120 meses.";
      monthsInput.focus();
      return;
    }
    row.dataset.rateioMeses = String(months);
    refreshRateSummary();
    dialog.close();
  };
  updatePreview();
  dialog.showModal();
  setTimeout(() => { monthsInput.focus(); monthsInput.select(); }, 50);
}
