function esc(v) {
  return String(v ?? "").replace(
    /[&<>\"]/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
  );
}
function col(n) {
  let s = "";
  while (n) {
    n--;
    s = String.fromCharCode(65 + (n % 26)) + s;
    n = Math.floor(n / 26);
  }
  return s;
}
window.vehicleAppBridge = {
  getState: () => dataState(),
  getNamespace: () => storageNamespace,
  hasNamespaceData: (namespace) => hasNamespaceData(safeStorageNamespace(namespace)),
  getNamespaceState: (namespace) => readNamespaceState(safeStorageNamespace(namespace)),
  getOfficialState: () => JSON.parse(JSON.stringify(officialInitialState || dataState())),
  activateNamespace: (namespace, options = {}) => {
    storageNamespace = safeStorageNamespace(namespace);
    const stored = readNamespaceState(storageNamespace);
    const hasStored = hasNamespaceData(storageNamespace);
    const state = options.seedState || (hasStored ? stored : options.useOfficial === false ? { movements:[], registers:[], drivers:[], vehicles:[], suppliers:[], paymentMethods:[], alerts:[] } : officialInitialState);
    window.vehicleAppBridge.applyState(state, { persist: true });
    window.dispatchEvent(new CustomEvent("vehicle-user-space-changed", { detail: { namespace: storageNamespace } }));
    return dataState();
  },
  applyState: (state, options = {}) => {
    if (!state) return;
    registers = (state.registers || defaults).map(normalizeRegister);
    vehicles = (state.vehicles || []).map(normalizeVehicle);
    drivers = state.drivers || []; suppliers = state.suppliers || []; paymentMethods = state.paymentMethods || [];
    enforceSingleDefaults();
    movements = (state.movements || []).map((m, i) => enforceItemGroup(normalizeMovement(m, i)));
    alerts = (state.alerts || []).map(normalizeAlertRecord).filter((item) => item.modelVersion === 2);
    ensureAlertData(); recalculateDistances();
    if (options.persist !== false) persistLocalState();
    try { renderAll(); } catch (_) {}
    setTimeout(() => evaluateAlerts(true), 0);
  },
};
