  rateioSummaries.sort((a, b) => String(a.movement.grupo).localeCompare(String(b.movement.grupo), "pt-BR") || String(a.movement.item).localeCompare(String(b.movement.item), "pt-BR") || String(a.movement.data_hora).localeCompare(String(b.movement.data_hora)));
  const competenceTable = rateioSummaries.length ? `<h3 class="rateio-list-title">Resumo dos itens rateados no período</h3><table class="responsive-table"><thead><tr><th>Grupo</th><th>Item</th><th>Competência inicial</th><th>Competência final</th><th>Parcelas no período</th><th>Valor da parcela</th><th>Total no período</th></tr></thead><tbody>${rateioSummaries.map((row) => `<tr><td data-label="Grupo">${e(row.movement.grupo || "—")}</td><td data-label="Item">${e(row.movement.item || "—")}</td><td data-label="Competência inicial">${e(competenceLabel(row.periodFirstCompetence))}</td><td data-label="Competência final">${e(competenceLabel(row.periodLastCompetence))}</td><td data-label="Parcelas no período" class="num">${row.considered}/${row.months}</td><td data-label="Valor da parcela" class="num">${money(row.installmentValue)}</td><td data-label="Total no período" class="num">${money(row.appropriated)}</td></tr>`).join("")}</tbody></table>` : '<p class="rule-note">Nenhum item de Manutenção ou Administrativo teve parcela apropriada no período. Os custos permanecem iguais à visão realizada.</p>';
  const biggestExpense = [...expenseRows].sort((a, b) => b.periodTotal - a.periodTotal)[0];

