let lastAiReport = null;

function escapeAiHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (char) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  })[char]);
}

function aiPeriodRows(vehicleId, start, end) {
  const vehicle = vehicles.find((v) => v.id === vehicleId);
  const name = vehicle?.nome || "";
  return movements.filter((m) => {
    const day = String(m.data_hora || "").slice(0, 10);
    return (m.veiculo_id === vehicleId || (!m.veiculo_id && m.veiculo === name)) &&
      day >= start && day <= end;
  });
}

function aiVehicleRows(vehicleId, end = "9999-12-31") {
  const vehicle = vehicles.find((v) => v.id === vehicleId);
  const name = vehicle?.nome || "";
  return movements.filter((movement) => {
    const date = String(movement.data_hora || "").slice(0, 10);
    return (movement.veiculo_id === vehicleId || (!movement.veiculo_id && movement.veiculo === name)) && date && date <= end;
  });
}

function buildExecutiveIntelligenceData(vehicleId, start, end, rows) {
  const vehicle = vehicles.find((v) => v.id === vehicleId);
  const allVehicleMovements = aiVehicleRows(vehicleId, end);
  const periodRows = [...rows];
  periodRows.periodFiltered = true;
  periodRows.periodStart = start;
  periodRows.periodEnd = end;
  const periodStats = stats(periodRows);
  const startDate = chartDate(start);
  const endDate = chartDate(end);
  const inclusiveDays = IndicatorCalc.inclusiveDaysBetween(start, end);
  const inclusiveMonths = IndicatorCalc.inclusiveMonthsBetween(start, end);
  const historyToEnd = allVehicleMovements.filter((movement) => String(movement.data_hora || "").slice(0, 10) <= end);
  const rollingStart = (months) => {
    const date = new Date(endDate);
    date.setMonth(date.getMonth() - months);
    date.setDate(date.getDate() + 1);
    return chartIso(date);
  };
  const lastMonthStart = rollingStart(1);
  const lastYearStart = rollingStart(12);
  const dateInRange = (movement, from, to = end) => {
    const date = String(movement.data_hora || "").slice(0, 10);
    return date && date >= from && date <= to;
  };
  const consumptionSummary = (fuelKey = "") => IndicatorCalc.detailedConsumptionSummary(
    validFuelMovements(historyToEnd, fuelKey),
    { monthStart: lastMonthStart, yearStart: lastYearStart, end },
  );
  const participationMetrics = IndicatorCalc.fuelParticipation(
    rows,
    (movement) => fuelSeriesIdentity(movement.item),
  );
  const participation = {
    gasolina: { liters: participationMetrics.byKey.gasolina.liters, records: participationMetrics.byKey.gasolina.records, share_percent: participationMetrics.byKey.gasolina.sharePercent },
    etanol: { liters: participationMetrics.byKey.etanol.liters, records: participationMetrics.byKey.etanol.records, share_percent: participationMetrics.byKey.etanol.sharePercent },
    diesel: { liters: participationMetrics.byKey.diesel.liters, records: participationMetrics.byKey.diesel.records, share_percent: participationMetrics.byKey.diesel.sharePercent },
    outros: { liters: participationMetrics.byKey.outros.liters, records: participationMetrics.byKey.outros.records, share_percent: participationMetrics.byKey.outros.sharePercent },
    total_liters: participationMetrics.total,
  };
  const financialGroups = [
    { key: "COMBUSTÍVEL", label: "Abastecimento" },
    { key: "MANUTENÇÃO", label: "Manutenção" },
    { key: "ADMINISTRATIVO", label: "Administrativo" },
    { key: "RECEITA", label: "Receitas" },
  ];
  const groupRows = IndicatorCalc.groupFinancialRows(
    rows,
    historyToEnd,
    financialGroups,
    inclusiveDays,
    lastYearStart,
    end,
  );
  const groups = groupRows.map((group) => ({
    group: group.key,
    label: group.label,
    period_total: group.periodTotal,
    daily_average: group.daily,
    monthly_average: group.monthly,
    last_year: group.annual,
    total_history: group.total,
  }));
  const periodFinancialTotals = IndicatorCalc.financialTotals(rows);
  const periodGross = periodFinancialTotals.gross;
  const periodIncome = periodFinancialTotals.income;
  const periodNet = periodFinancialTotals.net;
  const realizedIndicators = standardizedFinancialIndicators(periodNet, periodStats.km, inclusiveDays);

  const allocation = IndicatorCalc.allocationSchedule(allVehicleMovements, start, end);
  const competenceDetails = allocation.details;
  const rateioOriginalInPeriod = allocation.originalInPeriod;
  const rateioAppropriated = allocation.appropriatedInPeriod;
  const rateioSummaries = allocation.summaries.map((row) => ({
    group: row.movement.grupo,
    item: row.movement.item,
    date: String(row.movement.data_hora || "").slice(0, 10),
    months: row.months,
    installments_in_period: row.considered,
    competence_start: row.periodFirstCompetence,
    competence_end: row.periodLastCompetence,
    original_value: row.original,
    installment_value: row.installmentValue,
    appropriated_in_period: row.appropriated,
    accumulated_to_period_end: row.paidTotal,
    future_balance: row.balance,
  }));
  const competenceNet = IndicatorCalc.competenceNetCost(periodGross, rateioOriginalInPeriod, rateioAppropriated, periodIncome);
  const competenceIndicators = standardizedFinancialIndicators(competenceNet, periodStats.km, inclusiveDays);

  const registeredItems = new Map(registers.filter((item) => item.grupo === "MANUTENÇÃO").map((item) => [item.id, item]));
  const vehicleAlerts = alerts
    .filter((item) => item.vehicleId === vehicleId && item.modelVersion === 2 && registeredItems.has(item.itemId))
    .map((alertItem) => {
      const register = registeredItems.get(alertItem.itemId);
      const movement = allVehicleMovements
        .filter((row) => row.grupo === "MANUTENÇÃO" && (row.item_id === register.id || row.item === register.item))
        .sort((a, b) => new Date(b.data_hora) - new Date(a.data_hora))[0];
      return {
        item: register.item,
        active: Boolean(alertItem.active),
        status: alertStatus(alertItem),
        forecast: alertForecast(alertItem),
        last_date: movement?.data_hora || "",
        last_odometer_km: +movement?.hodometro_km || 0,
        last_value: movement?.valor == null ? null : +movement.valor || 0,
      };
    });
  const maintenanceSummary = {
    expired: vehicleAlerts.filter((row) => row.active && row.status === "VENCIDO").length,
    attention: vehicleAlerts.filter((row) => row.active && row.status === "ATENÇÃO").length,
    scheduled: vehicleAlerts.filter((row) => row.active && row.status === "PROGRAMADO").length,
    active: vehicleAlerts.filter((row) => row.active).length,
    without_history: vehicleAlerts.filter((row) => !row.last_date).length,
  };

  const itemTotals = IndicatorCalc.aggregateRecordsBy(
    rows.filter((movement) => movement.grupo !== "RECEITA"),
    (movement) => `${movement.grupo}|${movement.item || "Não informado"}`,
    (movement) => movement.valor,
  );
  const topItems = Object.entries(itemTotals)
    .map(([key, totals]) => {
      const separator = key.indexOf("|");
      return {
        group: separator >= 0 ? key.slice(0, separator) : "",
        item: separator >= 0 ? key.slice(separator + 1) : key,
        ...totals,
      };
    })
    .sort((a, b) => b.value - a.value)
    .slice(0, 10);

  const duplicateMap = new Map();
  rows.filter((movement) => movement.grupo !== "RECEITA").forEach((movement) => {
    const movementId = String(movement.movimento_id || movement.id || "");
    const normalizedItem = String(movement.item || "").trim().toLocaleLowerCase("pt-BR");
    const normalizedSupplier = String(movement.fornecedor || movement.local || "").trim().toLocaleLowerCase("pt-BR");
    const date = String(movement.data_hora || "").slice(0, 10);
    const value = (+movement.valor || 0).toFixed(2);
    const key = [date, movement.grupo, normalizedItem, value, normalizedSupplier].join("|");
    const entry = duplicateMap.get(key) || { date, group: movement.grupo, item: movement.item || "Não informado", value: +movement.valor || 0, supplier: movement.fornecedor || movement.local || "", movement_ids: new Set() };
    entry.movement_ids.add(movementId);
    duplicateMap.set(key, entry);
  });
  const exactDuplicateCandidates = [...duplicateMap.values()]
    .filter((entry) => entry.movement_ids.size > 1)
    .map((entry) => ({ date: entry.date, group: entry.group, item: entry.item, value: entry.value, supplier: entry.supplier, distinct_movements: entry.movement_ids.size }));

  const uniqueMovements = new Map();
  rows.forEach((row) => {
    const key = row.movimento_id || row.id;
    if (!uniqueMovements.has(key)) uniqueMovements.set(key, row);
  });
  const incompleteFuel = rows.filter((row) => row.grupo === "COMBUSTÍVEL" && row.tanque_completo !== "SIM");
  const completeFuel = validFuelMovements(rows);
  const missingOdometer = [...uniqueMovements.values()].filter((row) => !(+row.hodometro_km > 0)).length;
  const referenceValues = Object.values({
    etanol_cidade: +vehicle?.consumoEtanolCidade || 0, etanol_estrada: +vehicle?.consumoEtanolEstrada || 0,
    gasolina_cidade: +vehicle?.consumoGasolinaCidade || 0, gasolina_estrada: +vehicle?.consumoGasolinaEstrada || 0,
    diesel_cidade: +vehicle?.consumoDieselCidade || 0, diesel_estrada: +vehicle?.consumoDieselEstrada || 0,
  }).filter((value) => value > 0).length;
  let confidenceScore = 30;
  if (uniqueMovements.size >= 10) confidenceScore += 15;
  if (uniqueMovements.size >= 30) confidenceScore += 10;
  if (inclusiveDays >= 90) confidenceScore += 10;
  if (periodStats.km > 0) confidenceScore += 10;
  confidenceScore += completeFuel.length >= 5 ? 15 : completeFuel.length >= 2 ? 7 : 0;
  confidenceScore += vehicleAlerts.length || rows.some((row) => row.grupo === "MANUTENÇÃO") ? 5 : 0;
  if (referenceValues > 0) confidenceScore += 5;
  if (!uniqueMovements.size || missingOdometer / uniqueMovements.size <= 0.1) confidenceScore += 5;
  confidenceScore = Math.max(0, Math.min(100, confidenceScore));
  const confidenceLabel = confidenceScore >= 75 ? "Alta" : confidenceScore >= 50 ? "Média" : "Baixa";

  return {
    source: "Relatório Executivo MyCar+",
    calculation_version: APP_VERSION,
    analysis_scope: "completa",
    presentation: { consumption_decimals: 2, currency_decimals: 2, internal_precision: "integral" },
    period: { start, end, days: inclusiveDays, months: inclusiveMonths },
    usage: {
      distance_km: periodStats.km,
      daily_km: IndicatorCalc.perDay(periodStats.km, inclusiveDays),
      history_duration: formatHistoryDuration(allVehicleMovements),
    },
    consumption: {
      general: consumptionSummary(),
      ethanol: consumptionSummary("etanol"),
      gasoline: consumptionSummary("gasolina"),
      participation,
      incomplete_refuels_in_cost_only: incompleteFuel.length,
    },
    financial: {
      groups,
      realized: {
        gross_expenses: periodGross,
        income: periodIncome,
        net_cost: periodNet,
        cost_per_km: realizedIndicators.costPerKm,
        daily_cost: realizedIndicators.dailyCost,
        monthly_cost: realizedIndicators.monthlyCost,
      },
      competence: {
        original_rateio_values_in_period: rateioOriginalInPeriod,
        appropriated_rateio_values_in_period: rateioAppropriated,
        net_cost: competenceNet,
        cost_per_km: competenceIndicators.costPerKm,
        daily_cost: competenceIndicators.dailyCost,
        monthly_cost: competenceIndicators.monthlyCost,
        rateio_items: rateioSummaries,
      },
      top_items: topItems,
    },
    maintenance: { summary: maintenanceSummary, alerts: vehicleAlerts },
    evidence: {
      exact_duplicate_candidates: exactDuplicateCandidates,
      administrative_entries: rows.filter((row) => row.grupo === "ADMINISTRATIVO").sort((a, b) => (+b.valor || 0) - (+a.valor || 0)).slice(0, 30).map((row) => ({
        date: String(row.data_hora || "").slice(0, 10), item: row.item, value: +row.valor || 0,
        supplier: row.fornecedor || "", allocation_active: Boolean(row.rateio_ativo),
        allocation_months: Number(row.rateio_qtd_meses) || 0,
        competence_start: row.rateio_competencia_inicial || "",
      })),
    },
    confidence: {
      score: confidenceScore,
      label: confidenceLabel,
      basis: {
        movements: uniqueMovements.size,
        period_days: inclusiveDays,
        distance_available: periodStats.km > 0,
        complete_refuels: completeFuel.length,
        missing_odometer: missingOdometer,
        consumption_references: referenceValues,
      },
    },
    interpretation_rules: {
      taxes_insurance_are_periodic: true,
      dates_or_high_values_alone_do_not_prove_duplicate: true,
      duplicate_claim_requires_exact_duplicate_candidates: true,
      rateio_must_be_interpreted_by_competence: true,
      fuel_recommendations_must_be_limited_to_the_analyzed_period: true,
    },
  };
}

function buildAiIndicators(vehicleId, start, end) {
  const vehicle = vehicles.find((v) => v.id === vehicleId);
  const rows = aiPeriodRows(vehicleId, start, end);
  const executiveReport = buildExecutiveIntelligenceData(vehicleId, start, end, rows);
  const movementMap = new Map();
  rows.forEach((row) => {
    const key = row.movimento_id || row.id;
    if (!movementMap.has(key)) movementMap.set(key, row);
  });
  const uniqueMovements = [...movementMap.values()];
  const expenseRows = rows.filter((movement) => movement.grupo !== "RECEITA");
  const incomeRows = rows.filter((movement) => movement.grupo === "RECEITA");
  const odometers = uniqueMovements.map((movement) => +movement.hodometro_km || 0).filter(Boolean);
  const completeFuel = IndicatorCalc.validFuelCycles(rows);
  const incompleteFuel = rows.filter((movement) => movement.grupo === "COMBUSTÍVEL" && movement.tanque_completo !== "SIM");
  const byFuel = IndicatorCalc.aggregateFuelBy(rows, (movement) => movement.item || "Não informado");
  const suppliersSummary = IndicatorCalc.aggregateRecordsBy(
    expenseRows,
    (movement) => movement.fornecedor || "NI - Não informado",
    (movement) => movement.valor,
  );
  return {
    schema_version: 2,
    vehicle: {
      id: vehicleId, name: vehicle?.nome || "Veículo", plate: vehicle?.placa || "", active: vehicle?.ativo !== false,
      consumption_reference: {
        ethanol_city: +vehicle?.consumoEtanolCidade || 0, ethanol_road: +vehicle?.consumoEtanolEstrada || 0,
        gasoline_city: +vehicle?.consumoGasolinaCidade || 0, gasoline_road: +vehicle?.consumoGasolinaEstrada || 0,
        diesel_city: +vehicle?.consumoDieselCidade || 0, diesel_road: +vehicle?.consumoDieselEstrada || 0,
      },
    },
    period: executiveReport.period,
    sample: { movements: uniqueMovements.length, item_rows: rows.length, complete_refuels: completeFuel.length, incomplete_refuels: incompleteFuel.length },
    financial: executiveReport.financial.realized,
    usage: { ...executiveReport.usage, min_odometer: odometers.length ? Math.min(...odometers) : 0, max_odometer: odometers.length ? Math.max(...odometers) : 0 },
    fuel: { by_type: byFuel, ...executiveReport.consumption.general.total_history },
    costs_by_group: Object.fromEntries(executiveReport.financial.groups.map((group) => [group.group, group.period_total])),
    suppliers: suppliersSummary,
    maintenance: rows.filter((movement) => movement.grupo === "MANUTENÇÃO").map((movement) => ({
      date: String(movement.data_hora || "").slice(0, 10), item: movement.item,
      odometer_km: +movement.hodometro_km || 0, value: +movement.valor || 0,
    })).slice(-30),
    alert_snapshot: executiveReport.maintenance.alerts.map((item) => ({
      description: item.item, status: item.status, forecast: item.forecast,
      technical: true, active: item.active,
    })),
    quality: {
      missing_supplier: rows.filter((movement) => !movement.fornecedor || /^N\.?I/i.test(movement.fornecedor)).length,
      exact_duplicate_candidates: executiveReport.evidence.exact_duplicate_candidates,
    },
    executive_report: executiveReport,
  };
}

